        <?php $msgMedia=json_decode((string)($m['media_json']??''),true)?:[];if($msgMedia):?><div class="message-media"><?php foreach($msgMedia as $assetIndex=>$asset):$mime=(string)($asset['mime']??'');$url=InboxContact::mediaUrl($asset,(int)$m['id'],(int)$assetIndex);$name=(string)($asset['name']??'Adjunto');if($url==='')continue;if(in_array($mime,['image/jpeg','image/png','image/webp','image/gif'],true)):?><button type="button" class="message-image-preview" data-media-preview-url="<?=htmlspecialchars($url)?>" data-media-preview-name="<?=htmlspecialchars($name)?>" data-media-preview-kind="image"><img loading="lazy" referrerpolicy="no-referrer" src="<?=htmlspecialchars($url)?>" alt="<?=htmlspecialchars($name)?>"></button><?php elseif($mime==='application/pdf'):?><button type="button" class="soft message-pdf-preview" data-media-preview-url="<?=htmlspecialchars($url)?>" data-media-preview-name="<?=htmlspecialchars($name)?>" data-media-preview-kind="pdf"><i class="fa-solid fa-file-pdf"></i><span><?=htmlspecialchars($name)?></span></button><?php else:?><a class="message-file" href="<?=htmlspecialchars($url)?>" target="_blank" rel="noopener"><i class="fa-solid fa-paperclip"></i><span><?=htmlspecialchars($name)?></span></a><?php endif;endforeach?></div><?php endif?>
        <?php if($state==='failed'):?><div class="message-failure"><span><i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i> <?=$tr('No entregado','Not delivered')?></span><?php if(($m['outbox_state']??'')!=='superseded'):?><button type="button" class="message-retry" data-message-action="retry"><i class="fa-solid fa-rotate-right"></i> <?=$tr('Reintentar','Retry')?></button><?php endif?></div><?php endif?>
